// ocean/features.js FeatureSet vs Node 22 (Support/CoreReference.swift, generated by
// tools/fixtures/core-reference.mjs; ocean/features.json from the exporter takes over when it exists).
import XCTest
@testable import MaydayCore

final class FeatureSetTests: XCTestCase {
  func testScriptMatchesNode() throws {
    let ref = try JSONValue.parse(CoreReference.featureSetJSON)
    let pts = try ref["pts"].requireArray("pts").map { try $0.doublesOrFail("pt") }
    let samples = try ref["script"].requireArray("script")
    XCTAssertEqual(samples.count, 6)
    let fs = FeatureSet()
    var k = 0
    func check() throws {
      let s = samples[k]
      let label = s["label"].string ?? "#\(k)"
      k += 1
      XCTAssertEqual(fs.count, s["count"].int, "\(label) count")
      XCTAssertEqual(fs.active, s["active"].bool, "\(label) active")
      assertBitEqual(fs.residual, try s["residual"].doubleOrFail("residual"), "\(label) residual")
      assertBitEqual(pts.map { fs.heightAt($0[0], $0[1], $0[2]) }, try s["h"].doublesOrFail("h"), "\(label) heightAt")
      var flow = [Double]()
      for p in pts {
        let f = fs.flowAt(p[0], p[1])
        flow.append(f.x)
        flow.append(f.y)
      }
      assertBitEqual(flow, try s["f"].doublesOrFail("f"), "\(label) flowAt")
      assertFloatBitEqual(fs.uA, try s["uA"].doublesOrFail("uA"), "\(label) uA")
      assertFloatBitEqual(fs.uB, try s["uB"].doublesOrFail("uB"), "\(label) uB")
      assertFloatBitEqual(fs.uC, try s["uC"].doublesOrFail("uC"), "\(label) uC")
    }
    fs.set("r1", FeatureSpec(type: "rogue", x: 10, z: -5, dirX: 0.6, dirZ: 0.8, width: 30, length: 400, speed: 12, height: 9, strength: 0.9))
    fs.set("v1", FeatureSpec(type: "vortex", x: -20, z: 15, strength: 0.8, radius: 30))
    fs.set("w1", FeatureSpec(type: "whirlpool", x: 35, z: 20))
    try check() // after set
    for _ in 0..<30 { fs.update(1.0 / 60) }
    try check() // after 0.5 s
    fs.setDownwash(7.3, 7.3, 9.123456789, 0.7)
    try check() // downwash
    fs.remove("r1")
    for _ in 0..<60 { fs.update(1.0 / 60) }
    try check() // rogue removed +1 s
    XCTAssertFalse(fs.set("x", FeatureSpec(type: "bogus")))
    fs.set("v2", FeatureSpec(type: "vortex", x: 1, z: 2, strength: 3, spin: 1))
    fs.set("w2", FeatureSpec(type: "whirlpool", x: -5, z: -6, strength: 0.5, radius: 12))
    try check() // evict (r1 was fading → evicted first)
    XCTAssertEqual(fs.slots.map { $0.id }, ["v1", "w1", "v2", "w2"])
    for _ in 0..<120 { fs.update(1.0 / 30) }
    try check() // after 4 s
  }

  func testClearAndGet() {
    let fs = FeatureSet()
    fs.set("a", FeatureSpec(type: "vortex"))
    XCTAssertNotNil(fs.get("a"))
    fs.remove("a")
    XCTAssertNil(fs.get("a"))
    fs.clear()
    XCTAssertEqual(fs.count, 0)
    XCTAssertFalse(fs.active)
    XCTAssertEqual(fs.heightAt(0, 0), 0)
  }
}
